_KIND_OF = {"music_south_asia": "music", "music_arab_turk_persian": "music", "music_west": "music",
            "music_latin_asia_africa": "music"}
_WHO = {"quran": "a reciter whose Quran recitation many listeners search for", "naat": "a naat khwan or nasheed artist many listeners search for",
        "qawwali": "a qawwal, Sufi or folk singer many listeners search for", "music": "a singer, band or musician many listeners search for",
        "bhajan": "a bhajan or devotional singer many listeners search for", "gurbani": "a gurbani and shabad kirtan singer many listeners search for",
        "gospel": "a gospel and worship singer many listeners search for", "speaker": "a speaker, teacher or writer whose talks many listeners search for",
        "business": "a business, tech or sports figure whose talks and interviews many listeners search for", "politics": "a political figure whose speeches many listeners search for", "podcast": "a podcaster or host many listeners search for"}


def _ascii_slug(text):
    text = re.sub(r"[^a-z0-9]+", "-", text.lower()).strip("-")
    return text


def people_rows(data):
    """Rows (slug, full name, short name, words in a station name, kind, who) for every name, no repeats."""
    seen, rows = set(), []
    for key, blob in data.items():
        kind = _KIND_OF.get(key, key)
        for full in blob.split("|"):
            full = full.strip().replace("'", "")
            slug = _ascii_slug(full)
            if not full or not slug or slug in seen or len(slug) < 3:
                continue
            seen.add(slug)
            rows.append((slug, full, full, (full.lower(),), kind, _WHO[kind]))
    return rows
